// ======================== ConcurrentBitsetMemRequired ========================

// Verifies that requesting memory for a standard positive number of bits
// returns a valid, positive size.
TEST(ConcurrentBitsetTest, MemRequiredPositive) {
    const size_t mem_req = ConcurrentBitsetMemRequired(100);

    EXPECT_GT(mem_req, 0) << "Memory required for a positive number of bits "
                             "should be strictly greater than 0.";
    EXPECT_NE(mem_req, SIZE_MAX)
        << "Memory required for a valid number of bits should not return the "
           "SIZE_MAX error code.";
}

// Verifies that requesting memory for zero bits handles the edge case
// gracefully without returning an error.
TEST(ConcurrentBitsetTest, MemRequiredZero) {
    const size_t mem_req = ConcurrentBitsetMemRequired(0);

    EXPECT_NE(mem_req, SIZE_MAX) << "Memory required for 0 bits should not "
                                    "indicate an error (SIZE_MAX).";
}

// Verifies that requesting a negative number of bits correctly triggers the
// documented error state.
TEST(ConcurrentBitsetTest, MemRequiredNegative) {
    const size_t mem_req = ConcurrentBitsetMemRequired(-1);

    EXPECT_EQ(mem_req, SIZE_MAX) << "Memory required for a negative number of "
                                    "bits must return SIZE_MAX.";
}

// Verifies that memory requirements at common word-size boundaries scale
// monotonically.
TEST(ConcurrentBitsetTest, MemRequiredBoundary) {
    const size_t mem_req_64 = ConcurrentBitsetMemRequired(64);
    const size_t mem_req_65 = ConcurrentBitsetMemRequired(65);

    EXPECT_NE(mem_req_64, SIZE_MAX)
        << "Memory required for exactly 64 bits should be valid.";
    EXPECT_NE(mem_req_65, SIZE_MAX)
        << "Memory required for exactly 65 bits should be valid.";

    // The internal representation is abstracted, but it is physically
    // impossible for a bitset holding more bits to require less memory than a
    // smaller one.
    EXPECT_GE(mem_req_65, mem_req_64) << "Memory required for 65 bits must be "
                                         "greater than or equal to 64 bits.";
}

// ======================== ConcurrentBitsetCreateMt ========================

// Verifies that a bitset with a standard positive number of bits is
// successfully created, properly initialized to zero, and can be safely
// destroyed.
TEST(ConcurrentBitsetTest, CreateMtValid) {
    const int64_t expected_bits = 100;
    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(expected_bits);

    ASSERT_NE(bitset, nullptr) << "Bitset creation should succeed for a valid "
                                  "positive number of bits.";
    EXPECT_EQ(ConcurrentBitsetGetNumBits(bitset), expected_bits)
        << "The created bitset should report the exact number of bits "
           "requested.";

    // We check the boundaries and a middle point to guarantee initial state is
    // clean.
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 0, std::memory_order_relaxed))
        << "Bit 0 should be initialized to false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 50, std::memory_order_relaxed))
        << "Bit 50 should be initialized to false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 99, std::memory_order_relaxed))
        << "Bit 99 should be initialized to false.";

    ConcurrentBitsetDestroy(bitset);
}

