// ======================= ConcurrentBitsetCreateCopyMt =======================

// Verifies that a valid bitset with mixed bit states is correctly copied,
// preserving both the size and the exact state of all bits.
TEST(ConcurrentBitsetTest, CreateCopyMtValid) {
    const int64_t num_bits = 100;
    ConcurrentBitset* original = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(original, nullptr) << "Original bitset creation must succeed.";

    // Set some arbitrary bits to true to verify state copying
    ConcurrentBitsetSet(original, 0, std::memory_order_relaxed);
    ConcurrentBitsetSet(original, 5, std::memory_order_relaxed);
    ConcurrentBitsetSet(original, 63, std::memory_order_relaxed);

    ConcurrentBitset* copy = ConcurrentBitsetCreateCopyMt(original);

    ASSERT_NE(copy, nullptr)
        << "Bitset copy creation should succeed for a valid original bitset.";
    EXPECT_EQ(ConcurrentBitsetGetNumBits(copy), num_bits)
        << "The copied bitset must have the exact same number of bits as the "
           "original.";

    // Verify the states match the original perfectly
    EXPECT_TRUE(ConcurrentBitsetTest(copy, 0, std::memory_order_relaxed))
        << "Bit 0 should be true in the copy.";
    EXPECT_TRUE(ConcurrentBitsetTest(copy, 5, std::memory_order_relaxed))
        << "Bit 5 should be true in the copy.";
    EXPECT_TRUE(ConcurrentBitsetTest(copy, 63, std::memory_order_relaxed))
        << "Bit 63 should be true in the copy.";

    // Verify that unset bits remain unset
    EXPECT_FALSE(ConcurrentBitsetTest(copy, 1, std::memory_order_relaxed))
        << "Bit 1 should be false in the copy.";
    EXPECT_FALSE(ConcurrentBitsetTest(copy, 99, std::memory_order_relaxed))
        << "Bit 99 should be false in the copy.";

    ConcurrentBitsetDestroy(original);
    ConcurrentBitsetDestroy(copy);
}

