// =================== Core Bit Operations (Single-Threaded) ===================

// Verifies that the Set operation correctly returns the previous boolean state
// of the bit.
TEST(ConcurrentBitsetTest, SetReturnsPreviousState) {
    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(64);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    bool prev_state1 =
        ConcurrentBitsetSet(bitset, 5, std::memory_order_relaxed);
    EXPECT_FALSE(prev_state1) << "Setting an untouched bit should return false "
                                 "as its previous state.";

    bool prev_state2 =
        ConcurrentBitsetSet(bitset, 5, std::memory_order_relaxed);
    EXPECT_TRUE(prev_state2) << "Setting an already set bit should return true "
                                "as its previous state.";

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that the Reset operation correctly returns the previous boolean
// state of the bit and effectively changes the bit's value to 0.
TEST(ConcurrentBitsetTest, ResetReturnsPreviousState) {
    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(64);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    bool prev_state1 =
        ConcurrentBitsetReset(bitset, 10, std::memory_order_relaxed);
    EXPECT_FALSE(prev_state1) << "Resetting an untouched bit should return "
                                 "false as its previous state.";

    // We set the bit first so we can verify the reset transition from 1 to 0.
    ConcurrentBitsetSet(bitset, 10, std::memory_order_relaxed);

    bool prev_state2 =
        ConcurrentBitsetReset(bitset, 10, std::memory_order_relaxed);
    EXPECT_TRUE(prev_state2) << "Resetting a previously set bit should return "
                                "true as its previous state.";

    bool current_state =
        ConcurrentBitsetTest(bitset, 10, std::memory_order_relaxed);
    EXPECT_FALSE(current_state)
        << "Testing the bit after a reset should confirm it is now false.";

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that the Test operation accurately reflects the current state of
// bits, correctly distinguishing between modified and untouched bits.
TEST(ConcurrentBitsetTest, TestValidatesState) {
    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(64);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 0, std::memory_order_relaxed))
        << "Bit 0 should initially be false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 31, std::memory_order_relaxed))
        << "Bit 31 should initially be false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 63, std::memory_order_relaxed))
        << "Bit 63 should initially be false.";

    ConcurrentBitsetSet(bitset, 0, std::memory_order_relaxed);
    ConcurrentBitsetSet(bitset, 63, std::memory_order_relaxed);

    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 0, std::memory_order_relaxed))
        << "Bit 0 should evaluate to true after being set.";
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 63, std::memory_order_relaxed))
        << "Bit 63 should evaluate to true after being set.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 31, std::memory_order_relaxed))
        << "Bit 31 should remain false as it was never modified.";

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that bit operations at common 32-bit and 64-bit word boundaries
// do not inadvertently affect adjacent bits.
TEST(ConcurrentBitsetTest, WordBoundaryOperations) {
    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(256);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    // Set bits exactly at typical internal integer word boundaries.
    ConcurrentBitsetSet(bitset, 31, std::memory_order_relaxed);
    ConcurrentBitsetSet(bitset, 32, std::memory_order_relaxed);
    ConcurrentBitsetSet(bitset, 63, std::memory_order_relaxed);
    ConcurrentBitsetSet(bitset, 64, std::memory_order_relaxed);
    ConcurrentBitsetSet(bitset, 127, std::memory_order_relaxed);
    ConcurrentBitsetSet(bitset, 128, std::memory_order_relaxed);

    // Verify the targeted bits were set correctly.
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 31, std::memory_order_relaxed))
        << "Bit 31 should evaluate to true.";
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 64, std::memory_order_relaxed))
        << "Bit 64 should evaluate to true.";
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 127, std::memory_order_relaxed))
        << "Bit 127 should evaluate to true.";

    // Verify the adjacent bits remain unaffected to ensure there are no
    // off-by-one or bitmask overflow errors.
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 30, std::memory_order_relaxed))
        << "Bit 30 adjacent to a set boundary should remain false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 33, std::memory_order_relaxed))
        << "Bit 33 adjacent to a set boundary should remain false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 62, std::memory_order_relaxed))
        << "Bit 62 adjacent to a set boundary should remain false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 65, std::memory_order_relaxed))
        << "Bit 65 adjacent to a set boundary should remain false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 126, std::memory_order_relaxed))
        << "Bit 126 adjacent to a set boundary should remain false.";
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 129, std::memory_order_relaxed))
        << "Bit 129 adjacent to a set boundary should remain false.";

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that atomic operations on the maximum valid index (N - 1) function
// correctly without causing out-of-bounds errors or undefined behavior.
TEST(ConcurrentBitsetTest, MaxIndexOperations) {
    const int64_t num_bits = 100;
    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    const int64_t max_index = num_bits - 1;

    EXPECT_FALSE(
        ConcurrentBitsetTest(bitset, max_index, std::memory_order_relaxed))
        << "The maximum index bit should initially be false.";

    ConcurrentBitsetSet(bitset, max_index, std::memory_order_relaxed);
    EXPECT_TRUE(
        ConcurrentBitsetTest(bitset, max_index, std::memory_order_relaxed))
        << "The maximum index bit should be true after being set.";

    ConcurrentBitsetReset(bitset, max_index, std::memory_order_relaxed);
    EXPECT_FALSE(
        ConcurrentBitsetTest(bitset, max_index, std::memory_order_relaxed))
        << "The maximum index bit should be false after being reset.";

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that the API correctly accepts and handles standard C11/C++11 memory
// orders during Set, Reset, and Test operations.
TEST(ConcurrentBitsetTest, MemoryOrders) {
    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(64);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    // Test with sequentially consistent memory order
    ConcurrentBitsetSet(bitset, 1, std::memory_order_seq_cst);
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 1, std::memory_order_seq_cst))
        << "Bit 1 should be successfully tested after being set with "
           "memory_order_seq_cst.";
    ConcurrentBitsetReset(bitset, 1, std::memory_order_seq_cst);

    // Test with acquire-release semantics
    ConcurrentBitsetSet(bitset, 2, std::memory_order_release);
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 2, std::memory_order_acquire))
        << "Bit 2 should be successfully tested with memory_order_acquire "
           "after being set with memory_order_release.";
    ConcurrentBitsetReset(bitset, 2, std::memory_order_release);

    // Test with relaxed memory order
    ConcurrentBitsetSet(bitset, 3, std::memory_order_relaxed);
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 3, std::memory_order_relaxed))
        << "Bit 3 should be successfully tested after being set with "
           "memory_order_relaxed.";
    ConcurrentBitsetReset(bitset, 3, std::memory_order_relaxed);

    ConcurrentBitsetDestroy(bitset);
}

