// ===================== Concurrency & Thread-Safety Tests =====================

// Verifies that multiple threads can concurrently set distinct, non-overlapping
// bits in the bitset without causing data races or corrupting adjacent bits.
TEST(ConcurrentBitsetTest, ConcurrentSetDistinctBits) {
    const int64_t num_bits = 1000;
    const int num_threads = 10;
    const int64_t chunk_size = 100;
    const int64_t set_size = 50;

    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    auto worker = [](ConcurrentBitset* b, int64_t start, int64_t count) {
        for (int64_t i = 0; i < count; ++i) {
            ConcurrentBitsetSet(b, start + i, std::memory_order_relaxed);
        }
    };

    std::vector<std::thread> threads;
    // We spawn threads to each process a specific chunk, leaving the rest of
    // the chunk untouched to ensure concurrent modifications in the same
    // underlying machine words do not overwrite neighboring bit states.
    for (int i = 0; i < num_threads; ++i) {
        threads.emplace_back(worker, bitset, i * chunk_size, set_size);
    }

    for (auto& t : threads) {
        t.join();
    }

    // Verify the exact assigned bits are set and the unassigned bits remain
    // untouched.
    for (int i = 0; i < num_threads; ++i) {
        for (int64_t j = 0; j < chunk_size; ++j) {
            const int64_t bit_index = i * chunk_size + j;
            const bool expected_state = (j < set_size);

            if (expected_state) {
                EXPECT_TRUE(ConcurrentBitsetTest(bitset, bit_index,
                                                 std::memory_order_relaxed))
                    << "Assigned bit " << bit_index
                    << " should evaluate to true after concurrent sets.";
            } else {
                EXPECT_FALSE(ConcurrentBitsetTest(bitset, bit_index,
                                                  std::memory_order_relaxed))
                    << "Unassigned bit " << bit_index
                    << " should remain false and not be corrupted by adjacent "
                       "concurrent operations.";
            }
        }
    }

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that multiple threads can concurrently reset distinct,
// non-overlapping bits in a completely populated bitset without data races or
// interfering with adjacent bits.
TEST(ConcurrentBitsetTest, ConcurrentResetDistinctBits) {
    const int64_t num_bits = 1000;
    const int num_threads = 10;
    const int64_t chunk_size = 100;
    const int64_t reset_size = 50;

    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    // Pre-fill the bitset entirely with 1s so we can test transitioning to 0s
    // concurrently.
    for (int64_t i = 0; i < num_bits; ++i) {
        ConcurrentBitsetSet(bitset, i, std::memory_order_relaxed);
    }

    auto worker = [](ConcurrentBitset* b, int64_t start, int64_t count) {
        for (int64_t i = 0; i < count; ++i) {
            ConcurrentBitsetReset(b, start + i, std::memory_order_relaxed);
        }
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < num_threads; ++i) {
        threads.emplace_back(worker, bitset, i * chunk_size, reset_size);
    }

    for (auto& t : threads) {
        t.join();
    }

    // Verify the targeted bits were reset and the non-targeted bits remain set.
    for (int i = 0; i < num_threads; ++i) {
        for (int64_t j = 0; j < chunk_size; ++j) {
            const int64_t bit_index = i * chunk_size + j;
            const bool is_reset_target = (j < reset_size);

            if (is_reset_target) {
                EXPECT_FALSE(ConcurrentBitsetTest(bitset, bit_index,
                                                  std::memory_order_relaxed))
                    << "Targeted bit " << bit_index
                    << " should evaluate to false after concurrent resets.";
            } else {
                EXPECT_TRUE(ConcurrentBitsetTest(bitset, bit_index,
                                                 std::memory_order_relaxed))
                    << "Untargeted bit " << bit_index
                    << " should remain true and not be corrupted by adjacent "
                       "concurrent resets.";
            }
        }
    }

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that multiple threads continuously setting the exact same
// overlapping subset of bits do not cause crashes, data corruption, or leave
// the bits in an invalid state.
TEST(ConcurrentBitsetTest, ConcurrentSetOverlappingBits) {
    const int64_t num_bits = 256;
    const int num_threads = 8;
    const int num_iterations = 10000;

    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    // All threads will intentionally race to set this exact same subset of
    // bits.
    auto worker = [](ConcurrentBitset* b, int iterations) {
        for (int i = 0; i < iterations; ++i) {
            ConcurrentBitsetSet(b, 10, std::memory_order_relaxed);
            ConcurrentBitsetSet(b, 63, std::memory_order_relaxed);
            ConcurrentBitsetSet(b, 64, std::memory_order_relaxed);
            ConcurrentBitsetSet(b, 150, std::memory_order_relaxed);
        }
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < num_threads; ++i) {
        threads.emplace_back(worker, bitset, num_iterations);
    }

    for (auto& t : threads) {
        t.join();
    }

    // Regardless of the race conditions, the idempotent nature of Set means all
    // targeted bits must end up as 1.
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 10, std::memory_order_relaxed))
        << "Overlapped target bit 10 should definitively evaluate to true.";
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 63, std::memory_order_relaxed))
        << "Overlapped target bit 63 should definitively evaluate to true.";
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 64, std::memory_order_relaxed))
        << "Overlapped target bit 64 should definitively evaluate to true.";
    EXPECT_TRUE(ConcurrentBitsetTest(bitset, 150, std::memory_order_relaxed))
        << "Overlapped target bit 150 should definitively evaluate to true.";

    // Spot-check an adjacent, un-targeted bit to ensure the overlapping
    // contention didn't overflow.
    EXPECT_FALSE(ConcurrentBitsetTest(bitset, 65, std::memory_order_relaxed))
        << "Untargeted bit 65 should remain false despite heavy contention on "
           "bit 64.";

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that concurrent read (Test) and write (Set/Reset) operations on the
// same bit handle race conditions safely without segmentation faults, torn
// reads, or undefined behavior.
TEST(ConcurrentBitsetTest, ConcurrentSetAndTest) {
    const int64_t num_bits = 128;
    const int64_t target_bit = 42;
    const int num_iterations = 50000;

    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    // We use an atomic start flag to force the threads to spin up and begin
    // their tight loops at roughly the exact same moment to maximize thread
    // contention.
    std::atomic<bool> start_flag{false};

    std::thread toggler([&]() {
        while (!start_flag.load(std::memory_order_acquire)) {
            std::this_thread::yield();
        }
        for (int i = 0; i < num_iterations; ++i) {
            ConcurrentBitsetSet(bitset, target_bit, std::memory_order_relaxed);
            ConcurrentBitsetReset(bitset, target_bit,
                                  std::memory_order_relaxed);
        }
    });

    std::thread tester([&]() {
        while (!start_flag.load(std::memory_order_acquire)) {
            std::this_thread::yield();
        }
        for (int i = 0; i < num_iterations; ++i) {
            // We aren't asserting the result because it is inherently
            // non-deterministic. The goal here is memory safety—ensuring the
            // read instruction doesn't crash or trigger UB when colliding with
            // concurrent writes.
            volatile bool state = ConcurrentBitsetTest(
                bitset, target_bit, std::memory_order_relaxed);
            (void)state;
        }
    });

    start_flag.store(true, std::memory_order_release);

    toggler.join();
    tester.join();

    // If we reach this point, no segmentation faults or fatal assertions were
    // triggered by the race.
    SUCCEED() << "Concurrent toggling and testing completed without memory "
                 "safety violations or crashes.";

    ConcurrentBitsetDestroy(bitset);
}

// Verifies that operating on the bitset concurrently from multiple threads
// using a mixture of different C11 memory orders (e.g., relaxed,
// acquire-release, and sequentially consistent) completes safely without
// deadlocks or memory corruption.
TEST(ConcurrentBitsetTest, ConcurrentSetDifferentMemoryOrders) {
    const int64_t num_bits = 128;
    const int num_iterations = 20000;

    ConcurrentBitset* bitset = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(bitset, nullptr)
        << "Bitset creation must succeed for the test setup.";

    // Worker utilizing relaxed memory ordering for its operations.
    auto relaxed_worker = [](ConcurrentBitset* b, int iterations) {
        for (int i = 0; i < iterations; ++i) {
            ConcurrentBitsetSet(b, 10, std::memory_order_relaxed);
            ConcurrentBitsetReset(b, 20, std::memory_order_relaxed);
        }
    };

    // Worker utilizing sequentially consistent ordering to force a stricter
    // synchronization barrier.
    auto seq_cst_worker = [](ConcurrentBitset* b, int iterations) {
        for (int i = 0; i < iterations; ++i) {
            ConcurrentBitsetSet(b, 20, std::memory_order_seq_cst);
            ConcurrentBitsetReset(b, 10, std::memory_order_seq_cst);
        }
    };

    // Worker utilizing acquire and release semantics.
    auto acq_rel_worker = [](ConcurrentBitset* b, int iterations) {
        for (int i = 0; i < iterations; ++i) {
            ConcurrentBitsetSet(b, 30, std::memory_order_release);
            // We perform a test to trigger an acquire barrier while other
            // threads are writing.
            volatile bool state =
                ConcurrentBitsetTest(b, 30, std::memory_order_acquire);
            (void)state;
            ConcurrentBitsetReset(b, 30, std::memory_order_release);
        }
    };

    std::vector<std::thread> threads;

    // We spawn multiple instances of these workers to ensure overlapping
    // operations and heavily contend the underlying atomic variables with
    // varying barrier requirements.
    threads.emplace_back(relaxed_worker, bitset, num_iterations);
    threads.emplace_back(seq_cst_worker, bitset, num_iterations);
    threads.emplace_back(acq_rel_worker, bitset, num_iterations);
    threads.emplace_back(relaxed_worker, bitset, num_iterations);
    threads.emplace_back(seq_cst_worker, bitset, num_iterations);

    for (auto& t : threads) {
        t.join();
    }

    // Due to the deliberate race conditions between setting and resetting bits
    // 10 and 20, their final states are entirely non-deterministic. The pass
    // condition here is that the mixing of strict and relaxed memory barriers
    // didn't cause deadlocks, hardware exceptions, or undefined behavior
    // leading to a crash.
    SUCCEED() << "Concurrent bitset operations with mixed memory orders "
                 "completed without locking up or crashing.";

    ConcurrentBitsetDestroy(bitset);
}

