TEST(ConcurrentBitsetTest, SerializeDeserializeRoundtripChunked) {
    const int64_t num_bits = 256;
    ConcurrentBitset* source = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(source, nullptr)
        << "Source bitset creation must succeed for the test setup.";

    // Populate the bitset with a predictable but mixed pattern.
    for (int64_t i = 0; i < num_bits; i += 3) {
        ConcurrentBitsetSet(source, i, std::memory_order_relaxed);
    }

    const size_t total_size = ConcurrentBitsetGetSerializedSize(source);
    ASSERT_GT(total_size, 0) << "Serialized size must be positive.";

    ConcurrentBitset* dest = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(dest, nullptr) << "Destination bitset creation must succeed.";

    // The documentation notes the internal block size is typically
    // sizeof(unsigned long long) or smaller. Therefore, sizeof(unsigned long
    // long) is guaranteed to be a valid multiple of the internal block size,
    // making it a safe chunk size.
    const size_t chunk_size = sizeof(unsigned long long);
    std::vector<uint8_t> buffer(chunk_size);

    // Stream the data from source to destination in chunks.
    for (size_t offset = 0; offset < total_size; offset += chunk_size) {
        // If we are at the very end, we only request the remaining bytes,
        // ensuring we remain block-aligned because total_size is guaranteed to
        // be a multiple of the internal block size.
        const size_t current_request_size = (offset + chunk_size <= total_size)
                                                ? chunk_size
                                                : (total_size - offset);

        const size_t bytes_written = ConcurrentBitsetSerializeStreaming(
            source, offset, buffer.data(), current_request_size);
        EXPECT_EQ(bytes_written, current_request_size)
            << "Serialization should successfully write the requested chunk "
               "size at offset "
            << offset << ".";

        const size_t bytes_read = ConcurrentBitsetDeserializeStreaming(
            dest, offset, buffer.data(), current_request_size);
        EXPECT_EQ(bytes_read, current_request_size)
            << "Deserialization should successfully read the requested chunk "
               "size at offset "
            << offset << ".";
    }

    // Verify that the chunked streaming reconstructed the exact original state.
    for (int64_t i = 0; i < num_bits; ++i) {
        bool expected =
            ConcurrentBitsetTest(source, i, std::memory_order_relaxed);
        bool actual = ConcurrentBitsetTest(dest, i, std::memory_order_relaxed);
        EXPECT_EQ(actual, expected)
            << "Mismatch at bit index " << i << " after chunked roundtrip.";
    }

    ConcurrentBitsetDestroy(source);
    ConcurrentBitsetDestroy(dest);
}

// Verifies that a bitset with a capacity that does not perfectly align with
// common 64-bit word boundaries safely serializes and deserializes without
// padding bits corrupting the valid data or causing out-of-bounds memory
// access.
TEST(ConcurrentBitsetTest, SerializeDeserializeRoundtripUnalignedBitCounts) {
    // 67 bits spans across one full 64-bit word and slightly into a second one.
    const int64_t num_bits = 67;
    ConcurrentBitset* source = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(source, nullptr)
        << "Source bitset creation must succeed for the test setup.";

    // Set bits crossing the boundary and exactly at the uneven edge.
    ConcurrentBitsetSet(source, 0, std::memory_order_relaxed);
    ConcurrentBitsetSet(source, 63, std::memory_order_relaxed);
    ConcurrentBitsetSet(source, 64, std::memory_order_relaxed);
    ConcurrentBitsetSet(source, 66, std::memory_order_relaxed);

    const size_t serialized_size = ConcurrentBitsetGetSerializedSize(source);
    ASSERT_GT(serialized_size, 0) << "Serialized size must be positive.";

    std::vector<uint8_t> buffer(serialized_size);

    const size_t bytes_written = ConcurrentBitsetSerializeStreaming(
        source, 0, buffer.data(), buffer.size());
    EXPECT_EQ(bytes_written, serialized_size)
        << "Serialization must complete fully for unaligned bit capacities.";

    ConcurrentBitset* dest = ConcurrentBitsetCreateMt(num_bits);
    ASSERT_NE(dest, nullptr) << "Destination bitset creation must succeed.";

    const size_t bytes_read = ConcurrentBitsetDeserializeStreaming(
        dest, 0, buffer.data(), buffer.size());
    EXPECT_EQ(bytes_read, serialized_size)
        << "Deserialization must complete fully for unaligned bit capacities.";

    // Validate the explicitly set boundary bits.
    EXPECT_TRUE(ConcurrentBitsetTest(dest, 0, std::memory_order_relaxed))
        << "Bit 0 should be true.";
    EXPECT_TRUE(ConcurrentBitsetTest(dest, 63, std::memory_order_relaxed))
        << "Bit 63 should be true.";
    EXPECT_TRUE(ConcurrentBitsetTest(dest, 64, std::memory_order_relaxed))
        << "Bit 64 should be true.";
    EXPECT_TRUE(ConcurrentBitsetTest(dest, 66, std::memory_order_relaxed))
        << "Bit 66 should be true.";

    // Validate that an unset internal bit remains false.
    EXPECT_FALSE(ConcurrentBitsetTest(dest, 65, std::memory_order_relaxed))
        << "Bit 65 should be false.";

    ConcurrentBitsetDestroy(source);
    ConcurrentBitsetDestroy(dest);
}
